insert into contents (slug, type, status, title, subtitle, summary, cover_url, vimeo_id, duration_seconds, location_name, kp, lat, lng, tags, order_index, published_at) values ('avances-de-obra-auca-mahuida', 'especial'::content_type, 'published'::content_status, 'Avances de obra', 'Recorrido general por el frente de Auca Mahuida', 'Panorama del avance sobre el tramo norte: apertura de pista, acopio y los frentes de soldadura trabajando en paralelo.', null, '1182076624/6b9cc4eb7b', null, 'Auca Mahuida', 'KP 016', -37.772, -68.8, array['avance de obra', 'drone']::text[], 1, '2026-04-22T12:00:00Z') on conflict (slug) do nothing;
insert into content_blocks (content_id, type, position, data) select id, 'video', 0, '{"vimeoId":"1182076624/6b9cc4eb7b"}'::jsonb from contents where slug = 'avances-de-obra-auca-mahuida';
insert into content_blocks (content_id, type, position, data) select id, 'text', 1, '{"heading":"Varios frentes a la vez","body":"Una obra lineal no avanza como una línea: avanza como varios frentes simultáneos que se persiguen. Mientras la topografía replantea kilómetros adelante, atrás zanjean, más atrás sueldan y todavía más atrás tapan.\n\n**El cuello de botella se mueve.** Un día es el zanjeo por un tramo de roca, otro día es la disponibilidad de tubo en pista. Ese recorrido muestra el estado de todos los frentes en el mismo momento."}'::jsonb from contents where slug = 'avances-de-obra-auca-mahuida';
insert into contents (slug, type, status, title, subtitle, summary, cover_url, vimeo_id, duration_seconds, location_name, kp, lat, lng, tags, order_index, published_at) values ('planta-doble-junta', 'especial'::content_type, 'published'::content_status, 'Planta de Doble Junta', 'Acopio 1 · el armado del tubo de 24 m', 'Dos tubos de 12 metros se unen para formar tubos de 24, con arco sumergido y 90% de automatización.', null, '1211839891/6854d7fd48', null, 'Acopio 1', 'KP 032', -37.812, -68.63, array['soldadura', 'acopio']::text[], 2, '2026-04-15T12:00:00Z') on conflict (slug) do nothing;
insert into content_blocks (content_id, type, position, data) select id, 'video', 0, '{"vimeoId":"1211839891/6854d7fd48","caption":"Recorrido completo por la planta de doble junta."}'::jsonb from contents where slug = 'planta-doble-junta';
insert into content_blocks (content_id, type, position, data) select id, 'text', 1, '{"heading":"Rapidez y calidad en campo","body":"La planta fabrica tubos de 24 m uniendo dos de 12 m. El desafío fue armar la estructura en campo, con bases civiles in situ y vinculación de módulos en el lugar.\n\n**Acá lo que gira es el tubo, no la punta soldadora.** Eso, sumado al arco sumergido para el relleno, da una calidad superior a la manual y mayor rapidez. Alineadores internos y externos logran tolerancias milimétricas bajo normas API.\n\nProducimos entre 120 y 130 soldaduras diarias. Para igualar este rendimiento de forma manual, necesitaríamos el doble de personal y equipos."}'::jsonb from contents where slug = 'planta-doble-junta';
insert into content_blocks (content_id, type, position, data) select id, 'stats', 2, '{"items":[{"label":"Automatización","value":"90","unit":"%"},{"label":"Soldaduras / día","value":"120–130"},{"label":"Tubo final","value":"24","unit":"m"}]}'::jsonb from contents where slug = 'planta-doble-junta';
insert into content_blocks (content_id, type, position, data) select id, 'steps', 3, '{"heading":"El armado del tubo de 24 m","items":[{"title":"Biselado","body":"Ingresan los tubos para el biselado inicial."},{"title":"Pasada raíz","body":"Presentación y primera pasada de soldadura."},{"title":"Relleno exterior","body":"Relleno de la soldadura trabajando desde el exterior del caño."},{"title":"Soldadura interna","body":"Se ejecuta la soldadura interna, cerrando la etapa de unión."},{"title":"Ensayo US","body":"Ultrasonido con brazo robotizado: libera el caño o marca reproceso."}]}'::jsonb from contents where slug = 'planta-doble-junta';
insert into content_blocks (content_id, type, position, data) select id, 'gallery', 4, '{"caption":"Registro fotográfico de obra · Acopio 1","images":[]}'::jsonb from contents where slug = 'planta-doble-junta';
insert into contents (slug, type, status, title, subtitle, summary, cover_url, vimeo_id, duration_seconds, location_name, kp, lat, lng, tags, order_index, published_at) values ('topografia-y-geodeteccion', 'especial'::content_type, 'published'::content_status, 'Topografía y geodetección', 'Lo que se hace antes de tocar el suelo', 'El replanteo fija la traza en el terreno y la geodetección busca lo que ya está enterrado. Todo lo demás depende de estas dos tareas.', null, '1212437523/51a369fbc8', null, 'Tramo norte', 'KP 050', -37.848, -68.42, array['topografía', 'geodetección', 'previas']::text[], 3, '2026-04-09T12:00:00Z') on conflict (slug) do nothing;
insert into content_blocks (content_id, type, position, data) select id, 'video', 0, '{"vimeoId":"1212437523/51a369fbc8"}'::jsonb from contents where slug = 'topografia-y-geodeteccion';
insert into content_blocks (content_id, type, position, data) select id, 'text', 1, '{"heading":"Primero saber qué hay abajo","body":"El replanteo lleva al terreno lo que estaba en el proyecto: eje, ancho de pista, progresivas y los puntos donde la traza cruza algo.\n\nLa geodetección va después, y busca lo contrario: servicios existentes que no se ven. **Un ducto ajeno mal ubicado es el peor hallazgo posible durante el zanjeo**, y es exactamente lo que esta etapa está para evitar."}'::jsonb from contents where slug = 'topografia-y-geodeteccion';
insert into content_blocks (content_id, type, position, data) select id, 'video', 2, '{"vimeoId":"1211886800/87476bc641","caption":"Geodetección de servicios enterrados."}'::jsonb from contents where slug = 'topografia-y-geodeteccion';
insert into contents (slug, type, status, title, subtitle, summary, cover_url, vimeo_id, duration_seconds, location_name, kp, lat, lng, tags, order_index, published_at) values ('zanjeo-crucero-catriel', 'especial'::content_type, 'published'::content_status, 'Zanjeo', 'La zanja que define el resto de la obra', 'Profundidad, ancho y talud los decide el suelo. Cada cambio de material obliga a cambiar de equipo y de ritmo.', null, '1213332166/ebdf8fd524', null, 'Crucero Catriel', 'KP 095', -38.03, -67.955, array['movimiento de suelos']::text[], 4, '2026-04-02T12:00:00Z') on conflict (slug) do nothing;
insert into content_blocks (content_id, type, position, data) select id, 'video', 0, '{"vimeoId":"1213332166/ebdf8fd524"}'::jsonb from contents where slug = 'zanjeo-crucero-catriel';
insert into content_blocks (content_id, type, position, data) select id, 'text', 1, '{"body":"La zanja tiene que dar tapada suficiente sobre el caño y, al mismo tiempo, sostenerse abierta el tiempo que haga falta hasta que se baje el tubo. En suelo suelto eso significa abrir el talud; en roca, cambiar la retro por martillo y bajar el avance diario.\n\nEl suelo vegetal se retira aparte y se acopia al costado: vuelve a su lugar en la tapada, y no mezclado con el resto."}'::jsonb from contents where slug = 'zanjeo-crucero-catriel';
insert into content_blocks (content_id, type, position, data) select id, 'infographic', 2, '{"url":"","alt":"Sección transversal de la zanja y la pista de trabajo","caption":"Sección transversal de la pista. Cargar la infografía desde el backoffice."}'::jsonb from contents where slug = 'zanjeo-crucero-catriel';
insert into contents (slug, type, status, title, subtitle, summary, cover_url, vimeo_id, duration_seconds, location_name, kp, lat, lng, tags, order_index, published_at) values ('curvado-y-soldadura', 'especial'::content_type, 'published'::content_status, 'Curvado y soldadura', 'La geometría del terreno, tubo por tubo', 'Cada quiebre del terreno se traduce en un ángulo de curvado. Después, la línea regular une tubo con tubo sobre la pista.', null, '1213349389/2fd8bef934', null, 'Tramo medio', 'KP 133', -38.365, -68.02, array['curvado', 'soldadura']::text[], 5, '2026-03-26T12:00:00Z') on conflict (slug) do nothing;
insert into content_blocks (content_id, type, position, data) select id, 'video', 0, '{"vimeoId":"1213349389/2fd8bef934"}'::jsonb from contents where slug = 'curvado-y-soldadura';
insert into content_blocks (content_id, type, position, data) select id, 'text', 1, '{"heading":"Del relevamiento al ángulo","body":"El relevamiento topográfico define, para cada tramo, cuánto tiene que doblarse el caño para acompañar el terreno sin comprometer la sección.\n\nLa curvadora trabaja en frío, con mandril interno, en pasadas sucesivas de pocos grados. El control es permanente: **un ángulo de más obliga a descartar el tubo**."}'::jsonb from contents where slug = 'curvado-y-soldadura';
insert into content_blocks (content_id, type, position, data) select id, 'stats', 2, '{"items":[{"label":"Diámetro","value":"24","unit":"″"},{"label":"Pasadas por curva","value":"6–9"},{"label":"Tolerancia","value":"±0,5","unit":"°"}]}'::jsonb from contents where slug = 'curvado-y-soldadura';
insert into content_blocks (content_id, type, position, data) select id, 'video', 3, '{"vimeoId":"1214081693/7643f2c348","caption":"Soldadura de línea regular sobre la pista."}'::jsonb from contents where slug = 'curvado-y-soldadura';
insert into contents (slug, type, status, title, subtitle, summary, cover_url, vimeo_id, duration_seconds, location_name, kp, lat, lng, tags, order_index, published_at) values ('desfile-de-tubos', 'especial'::content_type, 'published'::content_status, 'Desfile de tubos', 'Del acopio a la pista', 'Los tubos de 24 m salen del acopio y se distribuyen a lo largo de la pista, en el orden exacto en que se van a soldar.', null, '1213343224/8be6d8152b', null, 'Medanito', 'KP 110', -38.19, -67.938, array['logística']::text[], 6, '2026-03-19T12:00:00Z') on conflict (slug) do nothing;
insert into content_blocks (content_id, type, position, data) select id, 'video', 0, '{"vimeoId":"1213343224/8be6d8152b"}'::jsonb from contents where slug = 'desfile-de-tubos';
insert into content_blocks (content_id, type, position, data) select id, 'text', 1, '{"body":"El desfile no es solo transporte: cada tubo tiene número, y el orden en que se deposita sobre la pista determina la secuencia de soldadura de los días siguientes. **Un error de orden se paga con jornadas perdidas.**"}'::jsonb from contents where slug = 'desfile-de-tubos';
insert into content_blocks (content_id, type, position, data) select id, 'video', 2, '{"vimeoId":"1213634536/c812f2449a","caption":"Empalmes entre tramos ya soldados."}'::jsonb from contents where slug = 'desfile-de-tubos';
insert into contents (slug, type, status, title, subtitle, summary, cover_url, vimeo_id, duration_seconds, location_name, kp, lat, lng, tags, order_index, published_at) values ('uam-alvs-allen', 'especial'::content_type, 'published'::content_status, 'UAM ALVS', 'Unidad de medición · fin de traza', 'Donde cierra la traza y arranca la medición fiscal hacia Puerto Rosales. El equipo, en un modelo 3D navegable.', null, null, null, 'Allen', 'KP 200', -38.935, -67.858, array['medición', 'comisionado', '3D']::text[], 7, '2026-03-12T12:00:00Z') on conflict (slug) do nothing;
insert into content_blocks (content_id, type, position, data) select id, 'sketchfab', 0, '{"modelId":"acc1c5fbf4d64e8e8b9fcd89d72dbdc8","title":"UAM_low","caption":"Modelo 3D de la unidad de medición, por Tronadores. Se puede rotar y acercar."}'::jsonb from contents where slug = 'uam-alvs-allen';
insert into content_blocks (content_id, type, position, data) select id, 'text', 1, '{"heading":"Medir es la última etapa","body":"En Allen cierra la traza y empieza otra cosa: la medición fiscal del crudo que sigue hacia Puerto Rosales.\n\nLa unidad de medición es el punto donde el volumen deja de ser una estimación y pasa a ser un número con valor contractual. Dos líneas al inicio, con previsión de ampliación futura."}'::jsonb from contents where slug = 'uam-alvs-allen';
insert into content_blocks (content_id, type, position, data) select id, 'gallery', 2, '{"caption":"Patio de tanques y sala eléctrica nueva","images":[]}'::jsonb from contents where slug = 'uam-alvs-allen';
